type CmdHandlers = { run: (g: Guide) => void; remove: (g: Guide) => void; add: (text: string) => void; reset: () => void }

// 자주 쓰는 명령 탭. 누르면 입력창에 넣기만 하고 실행은 엔터로 해요(/clear 처럼 되돌릴 수 없는 것도 있어서요).
