export const register: Register = (on, options) => {
  cfg = parseConfig(options)
  mode = cfg.handoffMode
  coachOn = cfg.coach
  sendConfirmOn = cfg.sendConfirm
  notifyOn = cfg.notify
  notifyDoneOn = cfg.notifyDone

  on('session.start', async ($, e, next) => {
    const storedMode = await $.store.get('mode')
    if (storedMode === 'ask' || storedMode === 'auto' || storedMode === 'off') mode = storedMode
    const storedCoach = await $.store.get('coach')
    if (typeof storedCoach === 'boolean') coachOn = storedCoach
    const storedSend = await $.store.get('sendConfirm')
    if (typeof storedSend === 'boolean') sendConfirmOn = storedSend
    const storedNotify = await $.store.get('notify')
    if (typeof storedNotify === 'boolean') notifyOn = storedNotify
    const storedDone = await $.store.get('notifyDone')
    if (typeof storedDone === 'boolean') notifyDoneOn = storedDone
    const storedAdded = (await $.store.get('cmdAdded')) as unknown
    if (Array.isArray(storedAdded)) cmdAdded = storedAdded.filter((g): g is Guide => !!g && typeof (g as Guide).name === 'string' && typeof (g as Guide).text === 'string')
    const storedHidden = (await $.store.get('cmdHidden')) as unknown
    if (Array.isArray(storedHidden)) cmdHidden = storedHidden.filter((x): x is string => typeof x === 'string')
    await loadBoard($)
    rootDir = await $.session.root().catch(() => '')
    await loadChanges($)
    await $.tool.register({ name: 'pin', description: DESCRIPTION, inputSchema: SCHEMA })
    void refreshUsage($).then(() => updateStatus($))
    $.clock.every(60_000, () => {
      void refreshUsage($).then(() => updateStatus($))
      void mailTick($)
      void calTick($)
    })
    // 명령어는 이름이 겹치면 던지니까 맨 뒤에서, 하나씩 감싸서 등록해요.
    await registerCommand($, { name: 'desk', description: '책상 열기: 할 일(일정 포함)·메일·사용량(이어가기 포함)·클립·명령·설정. text 는 글로 보기, check 는 처음 설정 점검', argumentHint: '[text|check]', immediate: true })
    await registerCommand($, { name: 'coach', description: '프롬프트 가이드 켜기·끄기', argumentHint: '[on|off]' })
    await registerCommand($, { name: 'desk-handoff', description: '대화를 새 대화로 넘겨요(이어가기)', argumentHint: '[now|ask|auto|off]', immediate: true })
    await registerCommand($, { name: 'clip', description: '클립보드의 글을 입력창에 붙여요. 이미지는 파일로 저장하고 경로를 붙여요', immediate: true })
    return next(e)
  })

  on('command.run', { command: 'desk' }, async ($, e) => {
    if (e.args.trim() === 'text') return { text: await deskText($) }
    if (e.args.trim() === 'check') {
      await runChecks($)
      return { text: ['처음 설정 점검', ...checks.flatMap(c => [`${CHECK_MARK[c.state]} ${c.label} · ${c.detail}`, ...(c.fix ? [`    → ${c.fix}`] : [])])].join('\n') }
    }
    openedByUser = true // 내가 직접 연 창은 입력창 위에 열려도 닫지 않아요.
    await refreshUsage($)
    updateStatus($)
    // 창을 다시 열었는데 «클립» 탭이 선택돼 있으면 바로 읽어요. «메일» 탭이면 받은편지함 제목을 읽어요.
    if (tab === 'clip') void watchClipboard($)
    if (tab === 'pin') void calOnTab($)
    if (tab === 'mail') void mailOnTab($)
    if (tab === 'settings') settingsOnTab($)
    await $.ui.open({ id: PANE, title: '책상', columns: cfg.paneColumns, focus: true, closeOnEscape: true })
    return {}
  })

  // /clip: 지금 클립보드를 읽어서 입력창에 바로 붙여요. 명령을 친 글이 지워진 뒤에 넣으려고 잠깐 기다려요.
  on('command.run', { command: 'clip' }, async ($) => {
    if (!(await isInteractive($))) return { text: '화면이 있는 세션에서만 쓸 수 있어요.' }
    const c = await readClipboard($)
    if (c.kind === 'empty') return { text: '클립보드가 비어 있어요.' }
    if (c.kind === 'error') return { text: `클립보드를 못 읽었어요: ${c.message}` }
    $.clock.after(150, () => void pasteClip($, c))
    return {}
  })

  on('command.run', { command: 'coach' }, async ($, e) => {
    const arg = e.args.trim()
    coachOn = arg === 'on' ? true : arg === 'off' ? false : !coachOn
    await $.store.set('coach', coachOn)
    $.ui.invalidate('ui.render')
    return { text: `프롬프트 가이드를 ${coachOn ? '켰어요' : '껐어요'}.` }
  })

  // 이름은 처음부터 /desk-handoff 예요. /handoff 는 다른 플러그인이나 내 명령이 이미 쓰는 일이 많아서, 그 명령을 가로채지 않으려고 듣지 않아요.
  on('command.run', { command: 'desk-handoff' }, async ($, e) => {
    const arg = e.args.trim()
    if (arg === 'now') {
      if (!(await isInteractive($))) return { text: '화면이 있는 세션에서만 넘길 수 있어요.' }
      void startHandoff($, true)
      return { text: '이어가기 메모를 쓰고 새 대화로 넘길게요.' }
    }
    if (arg === 'ask' || arg === 'auto' || arg === 'off') {
      mode = arg
      await $.store.set('mode', mode)
      $.ui.invalidate('ui.render')
      return { text: `이어가기 방식을 「${MODE_LABEL[mode]}」으로 바꿨어요.` }
    }
    return { text: `이어가기: ${MODE_LABEL[mode]}` + (lastBrief ? `\n마지막 메모: ${lastBrief.path}` : '') }
  })

  // 핀을 Claude 가 고치는 도구
  on('tool.call', { tool: TOOL }, async ($, e) => {
    if (e.agentId) return { deny: '핀은 메인 대화만 고쳐요.' }
    board = applyUpdate(board, e as Update)
    await saveBoard($)
    updateStatus($)
    $.ui.invalidate('ui.render')
    return { result: describeBoard(board) }
  })

  // Claude가 평소 쓰는 할 일 도구(TodoWrite·TaskCreate·TaskUpdate)를 옆에서 엿봐서 핀에 그대로 옮겨요.
  // 그래서 Claude가 따로 불러 주지 않아도 «이번 대화 할 일»이 채워져요.
  on('tool.call', { tool: [...MIRRORED_TOOLS] }, async ($, e, next) => {
    const r = await next(e)
    if (e.agentId) return r
    try {
      const failed = Boolean((r as { deny?: unknown }).deny || (r as { isError?: unknown }).isError)
      if (!failed) {
        const changed = mirrorTool(board, String(e.tool), e as unknown as Record<string, unknown>, r)
        if (changed) {
          board = changed
          await saveBoard($)
          updateStatus($)
          $.ui.invalidate('ui.render')
        }
      }
    } catch {
      // 핀이 못 따라가도 Claude의 일은 그대로 돼요.
    }
    return r
  })

  // 파일을 고친 도구(Edit·Write·NotebookEdit)가 성공하면 «이번 대화에서 고친 파일»에 올려요. 서브에이전트가 고친 것도 올려요.
  on('tool.call', { tool: [...EDIT_TOOLS] }, async ($, e, next) => {
    const r = await next(e)
    try {
      const failed = Boolean((r as { deny?: unknown }).deny || (r as { isError?: unknown }).isError)
      const path = editedPath(e)
      if (!failed && path) {
        changes = addChange(changes, path, await $.clock.now())
        await saveChanges($)
        $.ui.invalidate('ui.render')
      }
    } catch {
      // 목록이 못 따라가도 Claude의 일은 그대로 돼요.
    }
    return r
  })

  // Claude Code 가 «이 도구를 써도 될까요?» 창을 띄우면 알려요. 자리를 비웠을 때 몇십 분씩 멈춰 있지 않게요.
  // (권한 묻기를 꺼 둔 세션에서는 이 창이 안 떠서 알림도 안 와요)
  on('classic.PermissionRequest', async ($, e, next) => {
    void notifyPermission($, String(e.tool_name ?? ''), e.tool_input)
    return next(e)
  })

  // 모든 도구 호출을 한 번 봐요. 바깥으로 나가는 일이면 보내기 전에 물어요.
  // 이 훅이 고장 나도 도구는 그대로 실행돼요(대화가 멈추지 않게).
  on('tool.call', async ($, e, next) => {
    if (e.tool === TOOL) return next(e)
    if (e.tool === 'AskUserQuestion') {
      // Claude가 묻는 질문: 자리를 비웠을 때 알림으로 알려요. (우리 확인창은 이미 알림을 띄웠어요)
      if (!asking) {
        const q = ((e as { questions?: { question?: string }[] }).questions ?? [])[0]?.question
        void osNotify($, 'Claude가 질문해요', q ?? '')
      }
      return next(e)
    }
    const blocked = await sendCheck($, e as unknown as Record<string, unknown>)
    if (blocked) return blocked
    return next(e)
  })

  // 핀은 시스템 프롬프트 끝에 실려서, 답변에 매번 되풀이하지 않아도 돼요.
  on('prompt.compose', async ($, e, next) => {
    const { sections } = await next(e)
    if (board.todos.length + board.decisions.length === 0) return { sections }
    return { sections: [...sections, { id: 'side-desk:board', text: describeBoard(board), scope: 'session' }] }
  })

  // 핀 갱신은 대화창에 흐린 한 줄로만 남겨요. 내용은 옆 창에 있어요.
  on('ui.render', { component: 'ToolUse', props: { tool: TOOL } }, async ($, e) => {
    const { Text } = $.ui.resolve(e)
    const change = (e.props.input ?? {}) as Update
    const parts = [
      change.add_todos?.length && `할 일 +${change.add_todos.length}`,
      change.start_todo && `${change.start_todo} 시작`,
      change.done_todos?.length && `${change.done_todos.length}개 끝`,
      change.remove_todos?.length && `할 일 -${change.remove_todos.length}`,
      change.open_decisions?.length && `결정 +${change.open_decisions.length}`,
      change.decide?.length && `결정 ${change.decide.length}개 정함`,
    ].filter(Boolean)
    return <Text dimColor>{'핀: ' + (parts.join(', ') || '바뀐 것 없음')}</Text>
  })

  on('ui.render', { component: 'ToolResult', props: { tool: TOOL } }, async ($, e, next) =>
    e.props.isErrored ? next(e) : $.ui.resolve(e).Text({ children: [''] }),
  )

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const els = $.ui.resolve(e)
    const { Box, Button, Text } = els
    const inner = Math.max(10, (e.props.bodyColumns ?? 40) - 2)
    const now = await $.clock.now()
    const redraw = () => $.ui.invalidate('ui.render')
    const labelSet = tabLabelSet(inner + 1)
    // 옆이 아니라 입력창 위에 열렸다면(클래식 화면) 마우스가 안 눌려요. 클릭은 풀스크린 화면에서만 와요.
    const inline = e.props.placement === 'inline'
    lastPlacement = e.props.placement
    // 책상이 /desk 없이 그려질 때(플러그인을 다시 읽은 뒤 등)도 일정을 한 번은 읽어요. 읽기 시작하면 상태가 바로 바뀌어서 한 번만 불러요.
    if (tab === 'pin' && calState === 'idle') void loadCalendar($)
    const unfocused = e.props.isFocused === false
    // 풀스크린이 아닌 것이 확실할 때만 닫아요. 시작 직후 너비를 못 쟀거나(모름) 풀스크린인데 잠깐 좁은 때는 그대로 둬요.
    if (inline && e.viewport?.isFullscreen === false && !openedByUser && !inlineClosed) {
      // /desk 로 연 게 아니라 저절로(또는 이전 대화에서) 열린 창이에요. 눌리지도 않는 창이 입력창 위를 차지하지 않게 닫아요.
      inlineClosed = true
      void closeInlineDesk($)
      $.ui.toast('책상을 자동으로 열지 않았어요. 이 화면에서는 눌러서 쓸 수 없어요. /desk 로 열거나 /tui fullscreen 으로 바꿔 보세요.', { timeoutMs: 12000 })
    }
    const notice =
      inline || unfocused ? (
        <Box flexDirection="column" paddingLeft={1} paddingTop={1}>
          {inline && <Text color="warning" wrap="wrap">{'지금은 옆이 아니라 입력창 위에 열렸어요. 이 화면에서는 마우스로 눌러지지 않아요.'}</Text>}
          {inline && <Text dimColor wrap="wrap">{'옆에 붙이고 마우스도 쓰려면 /tui fullscreen 을 한 번 치세요.'}</Text>}
          {unfocused && <Text dimColor>{'키보드: Ctrl+X → Tab'}</Text>}
        </Box>
      ) : null
    const tabBtn = (name: TabName, label: string, hotkey: string) => (
      <Button
        key={'tab-' + name}
        label={label}
        hotkey={hotkey}
        plain
        dimColor={tab !== name}
        onPress={() => {
          tab = name
          redraw()
          // 클립 탭은 열 때 감시를 시작해요. 메일 탭은 열 때 받은편지함 제목을 읽어요.
          if (name === 'clip') void watchClipboard($)
          if (name === 'pin') void calOnTab($)
          if (name === 'mail') void mailOnTab($)
          if (name === 'settings') settingsOnTab($)
        }}
      />
    )
    const body =
      tab === 'pin'
        ? pinTab(els, inner, now, {
            explain: (path: string) => {
              void $.prompt.fill({ text: changePrompt(path) }).then(r => {
                $.ui.toast(r.isFilled ? '입력창에 넣었어요. Esc로 입력창에 돌아가 엔터를 누르면 물어봐요.' : '입력창에 못 넣었어요.', { timeoutMs: 6000 })
              })
            },
            refreshCal: () => void loadCalendar($),
          })
        : tab === 'usage'
          ? usageTab(els, inner, {
              now: () => void startHandoff($, true),
              cycle: () => {
                mode = nextMode(mode)
                void $.store.set('mode', mode)
                redraw()
              },
            })
          : tab === 'mail'
            ? mailTab(els, inner, now, {
                open: (row: MailRow) => void openMail($, row),
                back: () => {
                  mailView = undefined
                  redraw()
                },
                refresh: () => void loadMailList($),
                connect: () => connectGmail($),
                // 입력창을 이 글로 채우기만 해요. 보내기는 엔터로 해요.
                ask: m => {
                  void $.prompt.fill({ text: mailActionPrompt(m) }).then(r => {
                    $.ui.toast(r.isFilled ? '입력창에 넣었어요. Esc로 입력창에 돌아가 엔터를 누르면 시작해요.' : '입력창에 못 넣었어요.', { timeoutMs: 6000 })
                  })
                },
                browser: url => void openMailInBrowser($, url),
              })
          : tab === 'clip'
            ? clipTab(els, inner, {
                paste: () => {
                  const newest = clipList[0]
                  if (newest) void pasteItem($, newest)
                },
                refresh: () => void readClipList($).then(redraw),
                pick: (item: ClipItem) => void pasteItem($, item),
              })
            : tab === 'cmds'
            ? commandsTab(els, inner, {
                run: (g: Guide) => {
                  void $.prompt.fill({ text: guideCommand(g) }).then(r => {
                    $.ui.toast(r.isFilled ? `입력창에 ${guideCommand(g)} 를 넣었어요. 엔터를 누르면 실행돼요.` : '입력창에 못 넣었어요.', { timeoutMs: 6000 })
                  })
                },
                remove: (g: Guide) => {
                  if (isDefaultGuide(g)) cmdHidden = [...cmdHidden, guideCommand(g)]
                  else cmdAdded = cmdAdded.filter(x => guideCommand(x) !== guideCommand(g))
                  cmdNote = undefined
                  void saveGuide($)
                  redraw()
                },
                add: (text: string) => void addGuide($, text),
                reset: () => {
                  cmdAdded = []
                  cmdHidden = []
                  cmdNote = undefined
                  void saveGuide($)
                  redraw()
                },
              })
          : settingsTab(els, inner, {
                  send: () => {
                    sendConfirmOn = !sendConfirmOn
                    void $.store.set('sendConfirm', sendConfirmOn)
                    redraw()
                  },
                  notify: () => {
                    notifyOn = !notifyOn
                    void $.store.set('notify', notifyOn)
                    redraw()
                  },
                  notifyDone: () => {
                    notifyDoneOn = !notifyDoneOn
                    void $.store.set('notifyDone', notifyDoneOn)
                    redraw()
                  },
                  coach: () => {
                    coachOn = !coachOn
                    void $.store.set('coach', coachOn)
                    redraw()
                  },
                  recheck: () => void runChecks($),
                  testNotify: () => {
                    void osNotify($, '알림 시험', '이 알림이 보이면 잘 돼요', true)
                    $.ui.toast('알림을 보냈어요. 안 보이면 점검의 «알림» 줄을 보세요.', { timeoutMs: 6000 })
                  },
                })
    return (
      <Box flexDirection="column" width={inner + 2}>
        <Box flexDirection="row" flexWrap="wrap" columnGap={1} paddingLeft={1}>
          {TABS.map(t => tabBtn(t.name, t.labels[labelSet], t.hotkey))}
        </Box>
        {notice}
        {body}
      </Box>
    )
  })

  // 한 턴이 끝날 때마다: 사용량 갱신, 한도 경고, 이어가기 기준 확인
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined) return result
    turnCount++
    // 오래 걸린 일이 끝났을 때 알림. 짧은 턴은 화면을 보고 계시니 조용히 둬요.
    // «작업 끝 알림» 스위치를 켰을 때만 알려요(기본 꺼짐). 질문·승인 알림과 따로예요.
    if (notifyDoneOn && !e.isAborted && e.durationMs >= cfg.notifyMinSeconds * 1000) {
      const secs = Math.round(e.durationMs / 1000)
      const took = secs >= 60 ? `${Math.floor(secs / 60)}분 ${secs % 60}초` : `${secs}초`
      void osNotify($, `작업이 끝났어요 · ${took}`, String(e.answer ?? '').split('\n').find(l => l.trim()) ?? '', true)
    }
    // 답변이 질문으로 끝나면 «내가 정해야 하는 것»에 올려요. (내가 다음 말을 하면 내려가요)
    try {
      if (!e.isAborted) {
        const q = trailingQuestion(String(e.answer ?? ''))
        const updated = withAutoDecision(board, q)
        if (JSON.stringify(updated.decisions) !== JSON.stringify(board.decisions)) {
          board = updated
          await saveBoard($)
          $.ui.invalidate('ui.render')
        }
      }
    } catch {
      // 위와 같아요.
    }
    try {
      await refreshUsage($)
      updateStatus($)
      if (snap) {
        for (const w of snap.windows) {
          for (const level of [cfg.warnAt, 95]) {
            const id = `${w.kind}:${level}`
            if (w.percentUsed >= level && !warned.has(id)) {
              warned.add(id)
              $.ui.toast(`${WINDOW_LABEL[w.kind] ?? w.kind} 한도가 ${Math.round(w.percentUsed)}%예요 (${untilText(w.resetsAt, snap.updatedAt)})`, { timeoutMs: 10000 })
            }
          }
        }
      }
      await maybeHandoff($)
    } catch {
      // 책상이 실패해도 대화는 그대로 흘러가요.
    }
    return result
  })

  // 보내기 직전: 사람이 쓴 메시지면 연속 이어가기 횟수를 풀고, 프롬프트 가이드가 켜져 있으면 한 번 읽어 봐요.
  on('prompt.submit', async ($, e, next) => {
    const isPerson = e.origin.kind === 'composer' || e.origin.kind === 'sdk' || e.origin.kind === 'bridge'
    if (isPerson) {
      unattended = 0
      pausedSession = undefined
      if (inlinePending && !openedByUser) void closeInlineDesk($)
      // 내가 답했으니 «내가 정해야 하는 것»의 자동 항목을 내려요.
      if (board.decisions.some(d => d.id === 'auto')) {
        board = withAutoDecision(board, undefined)
        void saveBoard($)
        $.ui.invalidate('ui.render')
      }
    }
    if (!coachOn || !isPerson || COACH_SKIP.test(e.text) || e.text.trim().length < 8 || e.text.length > 1500) return next(e)
    if (!(await isInteractive($))) return next(e)

    $.ui.status('도움: 요청을 읽는 중…')
    let verdict: Verdict | undefined
    try {
      verdict = await coachReview($, e.text)
    } catch {
      verdict = undefined
    } finally {
      updateStatus($)
    }
    if (verdict === undefined || verdict.verdict === 'fine') return next(e)

    const SEND_NEW = '고친 문장으로 보내기'
    const SEND_MINE = '내 문장 그대로 보내기'
    const EDIT = '고쳐서 보내기'
    let choice: string
    try {
      choice = await $.ui.ask(`이렇게 쓰면 더 분명해요: ${verdict.why}\n\n${verdict.rewrite}\n\n어느 쪽으로 보낼까요?`, { header: '프롬프트 가이드', options: [SEND_NEW, SEND_MINE, EDIT] })
    } catch {
      return next(e) // 창을 닫으면 내 문장을 그대로 보내요.
    }
    if (choice === SEND_NEW) {
      $.ui.log(`고친 문장으로 보냈어요:\n${verdict.rewrite}`)
      return next({ ...e, text: verdict.rewrite })
    }
    if (choice === SEND_MINE) return next(e)
    if (choice === EDIT) {
      const rewrite = verdict.rewrite
      $.clock.after(150, () => void $.prompt.fill({ text: rewrite }))
      return { drop: '고친 문장을 입력창에 넣었어요. 고친 뒤 엔터를 누르세요.' }
    }
    // 「기타」에 직접 쓴 글이 보내고 싶은 문장이에요.
    $.ui.log(`직접 고친 문장으로 보냈어요:\n${choice}`)
    return next({ ...e, text: choice })
  })

  // 시작하는 순간에는 화면(터미널)이 아직 안 붙어 있을 수 있어요. 그러면 열지 못하고 끝나니, 화면이 붙을 때 한 번 더 시도해요.
  // autoOpenDesk 가 한 번만 열도록 막고 있어서 두 번 열리지는 않아요.
  on('session.attach', async ($, e, next) => {
    const r = await next(e)
    void autoOpenDesk($)
    return r
  })

  // /clear 뒤: 핀을 새 대화로 옮기고, 이어가기 메모를 읽으라는 첫 메시지를 넣어요.
  on('classic.SessionStart', async ($, e, next) => {
    const r = await next(e)
    if (e.source === 'resume' || e.source === 'fork') {
      await loadBoard($)
      await loadChanges($)
    }
    // 새 대화(/clear·인수인계)는 고친 파일 목록을 비우고 시작해요.
    if (e.source === 'clear') {
      changes = []
      $.ui.invalidate('ui.render')
    }
    // 시작·이어하기뿐 아니라 /tui 로 다시 뜬 세션도 있어서, clear·compact 만 빼고 한 번은 열어 봐요.
    if (e.source !== 'compact' && e.source !== 'clear') {
      void autoOpenDesk($)
      // 시작 순간에는 화면이 아직 안 붙어 있고 attach 신호도 안 올 때가 있어요. 몇 초 안에 한 번씩만 다시 봐요(한 번 열면 끝).
      for (const sec of [1, 3, 8, 20]) $.clock.after(sec * 1000, () => void autoOpenDesk($))
    }
    if (e.source !== 'clear') return r
    const p = pending
    pending = undefined
    if (!p) {
      board = emptyBoard()
      updateStatus($)
      return r
    }
    try {
      const newSession = await $.session.id()
      seededSession = newSession
      seedFloor = undefined
      board = p.board
      await saveBoard($)
      await $.store.set(`fired:${p.oldSession}`, `seeded:${newSession}`)
      const depth = await $.store.get('depth:next')
      if (typeof depth === 'number') await $.store.set(`depth:${newSession}`, depth)
      updateStatus($)
      $.ui.toast(`↪ 새 대화로 넘어왔어요${p.problem ? ' (요약 없이 사실만)' : ''}`, { timeoutMs: 10000 })
      $.prompt.submit({ text: seedText(p.oldSession, p.briefPath) }).catch((err: unknown) => {
        $.ui.toast(`첫 메시지가 거절됐어요. 메모 경로를 직접 붙여 주세요: ${p.briefPath}`, { timeoutMs: 20000 })
        $.ui.log(`첫 메시지 거절: ${String(err)}`)
      })
    } catch (err) {
      $.ui.log(`이어가기 시작 실패: ${String(err)}`)
    }
    return r
  })
}

files.hooks/lib.ts:
// side-desk 순수 함수 모음. `$`를 쓰지 않아서 register.tsx 어디서든 불러 쓸 수 있고, 테스트도 쉬워요.

// ───────────── 핀보드: 이번 대화의 할 일과 결정 ─────────────

export type Todo = { id: string; text: string; isDone: boolean; isActive?: boolean; ref?: string }
export type Decision = { id: string; text: string }
export type Board = { todos: Todo[]; decisions: Decision[] }
export type Update = {
  add_todos?: string[]
  start_todo?: string
  done_todos?: string[]
  remove_todos?: string[]
  open_decisions?: string[]
  decide?: { id: string; answer: string }[]
}

const nextId = (prefix: string, ids: string[]) =>
  prefix + (Math.max(0, ...ids.map(id => Number(id.slice(prefix.length)) || 0)) + 1)

export function applyUpdate(board: Board, change: Update): Board {
  let t = board.todos
  let d = board.decisions
  for (const text of change.add_todos ?? []) t = [...t, { id: nextId('t', t.map(x => x.id)), text, isDone: false }]
  for (const text of change.open_decisions ?? []) d = [...d, { id: nextId('d', d.map(x => x.id)), text }]
  const done = new Set(change.done_todos ?? [])
  const removed = new Set(change.remove_todos ?? [])
  const decided = new Set((change.decide ?? []).map(x => x.id))
  t = t.filter(x => !removed.has(x.id)).map(x => (done.has(x.id) ? { ...x, isDone: true } : x))
  // 진행 중인 할 일은 하나만. 끝나면 진행 표시도 내려요.
  if (change.start_todo) t = t.map(x => ({ ...x, isActive: x.id === change.start_todo }))
  t = t.map(x => (x.isDone && x.isActive ? { ...x, isActive: false } : x))
  d = d.filter(x => !decided.has(x.id))
  return { todos: t.slice(-40), decisions: d.slice(-20) }
}

export function describeBoard(board: Board): string {
  if (board.todos.length + board.decisions.length === 0) return 'side-desk 핀보드: 비어 있음'
  return [
    'side-desk 핀보드:',
    ...board.todos.map(t => `${t.id} [${t.isDone ? 'x' : t.isActive ? '>' : ' '}] ${t.text}`),
    ...board.decisions.map(d => `${d.id} [?] ${d.text}`),
  ].join('\n')
}

// ───────────── 사용량 ─────────────

export type UsageWindow = { kind: string; percentUsed: number; resetsAt?: string }
export const WINDOW_LABEL: Record<string, string> = { five_hour: '5시간', seven_day: '7일', spend_limit: '지출 한도' }

/** 터미널에서 차지하는 칸 수. 한글·한자·전각 글자는 두 칸이에요. */
const WIDE = /[\u1100-\u115f\u2e80-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe30-\ufe4f\uff00-\uff60\uffe0-\uffe6]/
export const cellWidth = (s: string) => [...s].reduce((w, ch) => w + (WIDE.test(ch) ? 2 : 1), 0)
/** 칸 수로 오른쪽을 채워요. (padEnd 는 글자 수로 채워서 한글이 섞이면 줄이 어긋나요) */
export const padCells = (s: string, cells: number) => s + ' '.repeat(Math.max(0, cells - cellWidth(s)))

export const k = (n: number) => (n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${Math.round(n / 1000)}k` : String(Math.round(n)))

export const bar = (percent: number, width: number) => {
  const filled = Math.max(0, Math.min(width, Math.round((percent / 100) * width)))
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

export function untilText(iso: string | undefined, now: number): string {
  if (iso === undefined) return ''
  const m = Math.max(0, Math.round((Date.parse(iso) - now) / 60000))
  if (m >= 60 * 24) return `${Math.round(m / 60 / 24)}일 뒤 초기화`
  if (m >= 60) return `${Math.floor(m / 60)}시간 ${m % 60}분 뒤 초기화`
  return `${m}분 뒤 초기화`
}

/** 이 대화를 시작한 뒤의 소모 속도. 지금 속도로 몇 시간 뒤에 100%가 되는지 같이 줘요. */
export function burn(w: UsageWindow, base: { at: number; windows: UsageWindow[] } | null, now: number) {
  const start = base?.windows.find(x => x.kind === w.kind)
  if (start === undefined || base === null) return null
  const hours = (now - base.at) / 3_600_000
  const used = w.percentUsed - start.percentUsed
  if (hours < 0.05 || used <= 0) return null
  const perHour = used / hours
  return { perHour, hoursLeft: (100 - w.percentUsed) / perHour }
}

export const hoursText = (h: number) => (h < 1 ? `${Math.round(h * 60)}분` : `${h.toFixed(1)}시간`)

// ───────────── 이어가기 메모 ─────────────

export type Msg = {
  role: string
  text: string
  toolUses: { tool: string; input: Record<string, unknown>; isError?: boolean; text?: string }[]
}

export type Facts = {
  filesModified: string[]
  commits: string[]
  lastUserMessage?: string
  tokens?: number
  depth?: number
}

const MAX_MESSAGES = 120
const MAX_MSG_CHARS = 2_000
const MAX_TRANSCRIPT_CHARS = 150_000
// 사용자 말이 아니라 하네스가 사용자 메시지로 흘려 넣는 신호들
const META_PREFIXES = ['Stop hook feedback', '[side-desk]', '[Image', '<system-reminder>', '<command-name>', '<local-command', '[auto-handoff]']
const EDIT_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])
const GIT_COMMIT_OUTPUT = /^\[[\w./-]+(?: \(root-commit\))? ([0-9a-f]{7,})\] (.+)$/m

export function userText(m: Msg): string | undefined {
  if (m.role !== 'user') return undefined
  const raw = m.text.trim()
  if (!raw) return undefined
  return META_PREFIXES.some(p => raw.startsWith(p)) ? undefined : raw
}

function commitSubject(command: string): string | undefined {
  if (!/\bgit\b[^\n|;&]*\bcommit\b/.test(command)) return undefined
  const heredoc = command.match(/<<\s*'?(\w+)'?\n([\s\S]*?)\n\1/)
  if (heredoc) return heredoc[2]?.trim().split('\n')[0]
  return command.match(/-m\s+(["'])(.+?)\1/)?.[2]
}

export function extractFacts(messages: readonly Msg[]): Facts {
  const files = new Set<string>()
  const commits: string[] = []
  let lastUserMessage: string | undefined
  for (const m of messages) {
    const said = userText(m)
    if (said) lastUserMessage = said
    for (const t of m.toolUses) {
      const path = t.input.file_path ?? t.input.notebook_path
      if (EDIT_TOOLS.has(t.tool) && typeof path === 'string' && !t.isError) files.add(path)
      if (t.tool !== 'Bash' || typeof t.input.command !== 'string' || t.isError) continue
      const out = t.text?.match(GIT_COMMIT_OUTPUT)
      const subject = out ? `${out[2]} (${out[1]})` : t.text === undefined ? commitSubject(t.input.command) : undefined
      if (subject && !commits.includes(subject)) commits.push(subject)
    }
  }
  const filesModified = [...files].slice(-25)
  return {
    filesModified,
    commits: commits.slice(-10),
    lastUserMessage,
  }
}

export function renderTranscript(messages: readonly Msg[]): string {
  const lines = messages.slice(-MAX_MESSAGES).map(m => {
    const role = m.role === 'user' && m.text.trim() && !userText(m) ? '시스템 신호(사용자 말 아님)' : m.role
    const text = m.text.length > MAX_MSG_CHARS ? m.text.slice(0, MAX_MSG_CHARS) + ' [잘림]' : m.text
    const tools = m.toolUses.map(t => `  [도구 ${t.tool}${t.isError ? ' 오류' : ''}] ${JSON.stringify(t.input).slice(0, 300)}`)
    return [`### ${role}`, text, ...tools].filter(Boolean).join('\n')
  })
  const joined = lines.join('\n\n')
  return joined.length > MAX_TRANSCRIPT_CHARS ? joined.slice(-MAX_TRANSCRIPT_CHARS) : joined
}

/** Haiku가 쓰는 소제목. 새 대화가 이 순서로 읽어요. */
export const BRIEF_HEADINGS = ['## 지금 하던 일', '## 정해진 것', '## 해 봤는데 막힌 길', '## 사용자에게 받아야 할 답', '## 다음에 할 일', '## 건드리기 전에 확인할 것'] as const

const list = (items: string[], empty: string) => (items.length ? items.map(i => `- ${i}`).join('\n') : empty)

export function factsBlock(f: Facts, board: Board): string {
  return [
    '## 코드로 뽑은 사실',
    '',
    `- 넘길 때 컨텍스트: ${f.tokens !== undefined ? k(f.tokens) + ' 토큰' : '알 수 없음'}`,
    f.depth !== undefined ? `- 이번이 ${f.depth}번째 이어가기` : '',
    '',
    '### 고친 파일 (Edit·Write)',
    list(f.filesModified, '없음'),
    '',
    '### 이 대화의 커밋',
    list(f.commits, '없음'),
    '',
    '### 핀보드',
    describeBoard(board),
    '',
    '### 사용자의 마지막 요청 (원문)',
    f.lastUserMessage ?? '찾지 못함',
  ]
    .filter(line => line !== undefined)
    .join('\n')
}

export function briefPrompt(messages: readonly Msg[], facts: Facts, board: Board): string {
  // 자료를 앞에, 지시를 뒤에 둬요.
  return `## 코드로 뽑은 사실\n${factsBlock(facts, board)}\n\n## 대화\n${renderTranscript(messages)}\n\n---\n\n` +
    `위는 Claude Code 작업 대화다. 대화가 길어져 새 대화로 넘긴다. 새 대화의 Claude가 이 글만 읽고 바로 이어서 일할 수 있게 이어가기 메모를 써라.\n` +
    `규칙:\n` +
    `- 대화에 나온 사실만 쓴다. 없는 파일, 번호, 숫자를 지어내지 않는다.\n` +
    `- 아래 소제목을 이 순서와 이름 그대로 쓰고, 비는 곳에는 "없음"이라고 쓴다.\n` +
    `- 쉬운 입말로 짧게 쓴다. (~했어요, ~해야 해요) 번역투와 영어식 문장은 쓰지 않는다.\n` +
    `- "사용자에게 받아야 할 답"에는 사용자가 아직 답하지 않은 질문과 승인만 쓴다.\n` +
    `- "해 봤는데 막힌 길"에는 시도했다가 안 된 방법과 그 이유를 쓴다. 새 대화가 같은 길을 가지 않게 하려는 칸이다.\n` +
    `- 시스템 신호(사용자 말 아님)로 표시된 글은 사용자가 한 말로 쓰지 않는다.\n\n` +
    BRIEF_HEADINGS.join('\n\n') + '\n'
}

export const isValidBrief = (text: string) => BRIEF_HEADINGS.some(h => text.includes(h))

export type BriefContext = { sessionId: string; cwd: string; transcript: string; at: string }

export function assembleBrief(ctx: BriefContext, facts: Facts, board: Board, haiku: string | undefined): string {
  const head = [
    '# 이어가기 메모',
    '',
    `- 이전 대화: ${ctx.sessionId}`,
    `- 작업 폴더: ${ctx.cwd}`,
    `- 대화 기록: ${ctx.transcript}`,
    `- 쓴 때: ${ctx.at}`,
    '',
    '## 읽는 법',
    haiku
      ? '작은 모델이 대화를 읽고 소제목 6개를 썼어요. 바꾼 파일과 커밋은 코드로 뽑았어요.'
      : '작은 모델의 요약이 없어서 코드로 뽑은 사실만 있어요. 나머지는 대화 기록을 직접 읽으세요.',
    '여기 적힌 건 출발점일 뿐 확정된 사실이 아니에요. 쓰기 전에 `git status`나 파일을 열어 한 번 확인하세요.',
    '이 폴더에 지침 파일(CLAUDE.md)이 있다면 새 대화가 이미 읽었어요. 거기 적힌 규칙이 이 글보다 앞서요.',
  ].join('\n')
  return [head, haiku?.trim(), factsBlock(facts, board)].filter(Boolean).join('\n\n') + '\n'
}

export const shortId = (sessionId: string) => sessionId.slice(0, 8)

export function seedText(oldSession: string, briefPath: string): string {
  return `[side-desk] ↪ 이어가기 ${shortId(oldSession)}. 이전 대화가 길어져서 새 대화로 넘어왔어요. ` +
    `아무것도 하기 전에 ${briefPath} 를 읽고, 「다음에 할 일」부터 이어 가세요. ` +
    `첫 답변의 첫 줄에 "↪ 이어가기 받음 (${shortId(oldSession)})"라고 적으세요. ` +
    `브리프에 적힌 파일·커밋은 열어서 한 번 확인한 뒤에 쓰세요.`
}

// ───────────── 프롬프트 코치 ─────────────

export const COACH_SYSTEM = `너는 사용자가 Claude Code에 보내려는 요청을 보내기 직전에 한 번 읽어 보는 검수자다.
고쳐 보내면 결과가 분명히 나아질 때만 고친다. 대부분의 요청은 그대로 괜찮다.

고칠 만한 경우는 이것뿐이다.
- 무엇을 하라는지 흐릿하다. ("이거 고쳐줘"인데 대상이 안 보인다)
- 끝났다고 볼 기준이 없다.
- 서로 상관없는 요청이 한 문장에 뭉쳐 있다.
- 건드리면 안 되는 범위를 알려야 하는데 빠졌다.

사용자는 음성으로 말해서 입력할 때가 많다. 문장이 끊기거나 말투가 흐트러져 있을 수 있다. 뜻이 통하면 괜찮은 요청이다.
최근 대화를 보고 "이거", "그거", "아까 그 파일"이 무엇인지 풀 수 있으면 괜찮다. 글만 따로 보면 흐릿해도 대화로 분명하면 문제가 아니다.

고칠 때는 가장 작게 고친다.
- 사용자가 쓴 낱말과 순서를 그대로 두고, 빠진 것(대상 파일이나 영역, 끝났다고 볼 기준, 건드리지 말 것)만 덧붙인다.
- 고친 글은 사용자가 쓴 글에 몇 마디 더한 것처럼 읽혀야 한다. 새 요청이 되면 안 된다.
- 요청의 종류를 바꾸지 않는다. 오류 제보는 제보로, 질문은 질문으로, 부탁은 부탁으로 둔다.
- 사용자가 하지 않은 질문, 요구, 산출물을 새로 넣지 않는다.
- "일단", "먼저", "만" 같은 범위 말과 사용자가 밝힌 조건·취향은 그대로 둔다.
- 고친 글은 한국어 입말로 쓴다. 번역투와 영어식 문장 구조는 쓰지 않는다.
- "네", "좋아", "진행해"처럼 대화에 답하는 말은 괜찮다.

답은 JSON 하나로만 한다.
{"verdict":"fine"} 또는 {"verdict":"improve","why":"<30자 안쪽 이유>","rewrite":"<고친 요청>"}`

export type Verdict = { verdict: 'fine' } | { verdict: 'improve'; why: string; rewrite: string }

/** 프롬프트 가이드를 건너뛰는 요청: 명령어, 짧은 대답, 링크만 있는 글 */
export const COACH_SKIP =
  /^\s*([/!#]|https?:\/\/\S+\s*$|(네|예|응|아니|아니요|좋아|좋아요|그래|그래요|그렇게|맞아|맞아요|진행|진행해|진행해줘|계속|계속해|해줘|ok|okay|yes|no|y|n)[\s.!요?]*$)/i

export function parseVerdict(text: string): Verdict | undefined {
  const json = /\{[\s\S]*\}/.exec(text)?.[0]
  if (json === undefined) return undefined
  try {
    const v = JSON.parse(json) as Partial<{ verdict: string; why: string; rewrite: string }>
    if (v.verdict === 'improve' && typeof v.rewrite === 'string' && v.rewrite.trim() !== '') {
      return { verdict: 'improve', why: v.why ?? '', rewrite: v.rewrite.trim() }
    }
    return { verdict: 'fine' }
  } catch {
    return undefined
  }
}

/** 고친 글이 원래 글의 낱말을 얼마나 남겼는지. 조사가 달라져도 맞도록 앞 두 글자로 견줘요. */
export function keptShare(prompt: string, rewrite: string): number {
  const stems = (s: string) => new Set((s.toLowerCase().match(/[\p{L}\p{N}_./-]{2,}/gu) ?? []).map(w => w.slice(0, 2)))
  const original = stems(prompt)
  if (original.size < 3) return 1
  const kept = stems(rewrite)
  let hits = 0
  for (const w of original) if (kept.has(w)) hits++
  return hits / original.size
}

export function recentTurns(messages: readonly { role: string; text: string }[], max = 6, perMessage = 700): string {
  return messages
    .filter(m => m.text.trim() !== '')
    .slice(-max)
    .map(m => `${m.role === 'user' ? '사용자' : 'Claude'}: ${m.text.length > perMessage ? `…${m.text.slice(-perMessage)}` : m.text}`)
    .join('\n\n')
}

// ───────────── 클립보드 ─────────────
// 모드에는 클립보드를 «읽는» 기능이 없어서(쓰기만 있어요) PowerShell로 읽어요.
// 사용자가 열어 보거나 /clip 을 쓴 순간에만 읽고, 따로 기록해 두지 않아요.

export type Clip =
  | { kind: 'empty' }
  | { kind: 'error'; message: string }
  | { kind: 'text'; text: string; chars: number; truncated: boolean }
  | { kind: 'image'; path: string; size: string; bytes: number }
  | { kind: 'files'; files: string[] }

export const CLIP_MAX = 30_000

/** 윈도우 PowerShell에서 실행해요. 첫 줄이 종류(TEXT·IMAGE·FILES·EMPTY·ERROR), 나머지가 내용이에요. */
export const CLIP_SCRIPT = [
  'try {',
  "Add-Type -AssemblyName System.Windows.Forms,System.Drawing;",
  '[Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false);',
  'if ([System.Windows.Forms.Clipboard]::ContainsImage()) {',
  "  $dir = Join-Path $env:USERPROFILE '.claude\\state\\side-desk\\clips';",
  '  New-Item -ItemType Directory -Force -Path $dir | Out-Null;',
  "  Get-ChildItem $dir -Filter 'clip-*.png' | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-1) } | Remove-Item -Force -ErrorAction SilentlyContinue;",
  '  $img = [System.Windows.Forms.Clipboard]::GetImage();',
  "  $p = Join-Path $dir ('clip-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.png');",
  '  $img.Save($p, [System.Drawing.Imaging.ImageFormat]::Png);',
  "  'IMAGE'; $p; ('' + $img.Width + 'x' + $img.Height); (Get-Item $p).Length",
  '} elseif ([System.Windows.Forms.Clipboard]::ContainsFileDropList()) {',
  "  'FILES'; [System.Windows.Forms.Clipboard]::GetFileDropList() | ForEach-Object { $_ }",
  '} elseif ([System.Windows.Forms.Clipboard]::ContainsText()) {',
  "  'TEXT'; [System.Windows.Forms.Clipboard]::GetText()",
  "} else { 'EMPTY' }",
  "} catch { 'ERROR'; $_.Exception.Message }",
].join('\n')

export function parseClip(stdout: string): Clip {
  const lines = stdout.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n')
  const kind = (lines[0] ?? '').replace(/^\uFEFF/, '').trim()
  const rest = lines.slice(1)
  if (kind === 'TEXT') {
    const full = rest.join('\n').replace(/\n+$/, '')
    if (!full.trim()) return { kind: 'empty' }
    return { kind: 'text', text: full.slice(0, CLIP_MAX), chars: full.length, truncated: full.length > CLIP_MAX }
  }
  if (kind === 'IMAGE') {
    const [path, size, bytes] = rest.map(s => s.trim())
    if (!path) return { kind: 'error', message: '이미지 경로를 못 받았어요' }
    return { kind: 'image', path, size: size ?? '', bytes: Number(bytes) || 0 }
  }
  if (kind === 'FILES') {
    const files = rest.map(s => s.trim()).filter(Boolean)
    return files.length > 0 ? { kind: 'files', files } : { kind: 'empty' }
  }
  if (kind === 'ERROR') return { kind: 'error', message: rest.join(' ').trim().slice(0, 160) || '알 수 없는 오류' }
  return { kind: 'empty' }
}

/** 입력창에 넣을 글. 이미지는 파일 경로를 넣어요(클로드가 그 경로로 이미지를 읽어요). */
export function clipInsertText(c: Clip, toHost: (p: string) => string): string {
  if (c.kind === 'text') return c.text + (c.truncated ? `\n…(${CLIP_MAX.toLocaleString('en-US')}자까지만 넣었어요)` : '')
  if (c.kind === 'image') return `[클립보드 이미지] ${toHost(c.path)}`
  if (c.kind === 'files') return c.files.map(toHost).join('\n')
  return ''
}

/** 화면에 보여 줄 한 줄 설명 */
export function clipTitle(c: Clip | undefined): string {
  if (!c) return '아직 안 읽었어요'
  if (c.kind === 'text') return `글 · ${c.chars.toLocaleString('en-US')}자`
  if (c.kind === 'image') return `이미지 · ${c.size} · ${Math.max(1, Math.round(c.bytes / 1024))}KB`
  if (c.kind === 'files') return `파일 ${c.files.length}개`
  if (c.kind === 'error') return `못 읽었어요: ${c.message}`
  return '비어 있어요'
}

// ───────────── 클립보드 기록 (윈도우 Win+V) ─────────────
// 이 모드가 따로 기록하지 않아요. 윈도우가 이미 가진 기록(최근 25개)을 읽어서 보여 줘요.
// 기록이 꺼져 있으면(설정 > 시스템 > 클립보드) 지금 클립보드 한 개만 보여 줘요.

export type ClipItem = { id: string; at: string; kind: 'text' | 'image' | 'files' | 'other'; chars?: number; preview?: string }

const WINRT_SETUP = [
  'Add-Type -AssemblyName System.Runtime.WindowsRuntime',
  '[Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)',
  '$null = [Windows.ApplicationModel.DataTransfer.Clipboard, Windows.ApplicationModel.DataTransfer, ContentType=WindowsRuntime]',
  '$null = [Windows.ApplicationModel.DataTransfer.ClipboardHistoryItemsResult, Windows.ApplicationModel.DataTransfer, ContentType=WindowsRuntime]',
  '$null = [Windows.Storage.Streams.RandomAccessStreamReference, Windows.Storage.Streams, ContentType=WindowsRuntime]',
  '$null = [Windows.Storage.Streams.IRandomAccessStreamWithContentType, Windows.Storage.Streams, ContentType=WindowsRuntime]',
  "$asTask = ([System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]",
  'function Await($op, $type) { $t = $asTask.MakeGenericMethod($type).Invoke($null, @($op)); [void]$t.Wait(5000); $t.Result }',
  '$res = Await ([Windows.ApplicationModel.DataTransfer.Clipboard]::GetHistoryItemsAsync()) ([Windows.ApplicationModel.DataTransfer.ClipboardHistoryItemsResult])',
  "if ($res.Status -ne 'Success') { 'STATUS ' + $res.Status; return }",
]

/**
 * 변화를 «듣는» 감시 스크립트. 프로세스를 한 번만 띄우고, 클립보드 번호(GetClipboardSequenceNumber)가
 * 바뀔 때만 기록 목록을 BEGIN…END로 내보내요. 10초마다 TICK 한 줄을 보내서 모드가 «아직 필요한가»를 볼 수 있게 해요.
 * 번호 확인은 숫자 하나를 읽는 일이라 새 프로세스도, 창도, 눈에 띄는 부하도 없어요.
 */
export const CLIP_WATCH_SCRIPT = [
  "$ErrorActionPreference = 'Stop'",
  'Add-Type -AssemblyName System.Runtime.WindowsRuntime',
  "Add-Type -Namespace Ft -Name Clip -MemberDefinition '[System.Runtime.InteropServices.DllImport(\"user32.dll\")] public static extern uint GetClipboardSequenceNumber();'",
  '[Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)',
  '$null = [Windows.ApplicationModel.DataTransfer.Clipboard, Windows.ApplicationModel.DataTransfer, ContentType=WindowsRuntime]',
  '$null = [Windows.ApplicationModel.DataTransfer.ClipboardHistoryItemsResult, Windows.ApplicationModel.DataTransfer, ContentType=WindowsRuntime]',
  "$asTask = ([System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]",
  'function Await($op, $type) { $t = $asTask.MakeGenericMethod($type).Invoke($null, @($op)); [void]$t.Wait(5000); $t.Result }',
  'function Emit {',
  '  try {',
  '    $res = Await ([Windows.ApplicationModel.DataTransfer.Clipboard]::GetHistoryItemsAsync()) ([Windows.ApplicationModel.DataTransfer.ClipboardHistoryItemsResult])',
  "    'BEGIN'",
  "    if ($res.Status -ne 'Success') { 'STATUS ' + $res.Status }",
  '    else {',
  '      $n = 0',
  '      foreach ($it in $res.Items) {',
  '        $n++; if ($n -gt 12) { break }',
  '        $c = $it.Content',
  "        $o = [ordered]@{ id = [string]$it.Timestamp.UtcTicks; at = $it.Timestamp.ToLocalTime().ToString('HH:mm:ss'); kind = 'other' }",
  "        if ($c.Contains('Bitmap')) { $o.kind = 'image' }",
  "        elseif ($c.Contains('Text')) {",
  "          $o.kind = 'text'",
  '          $s = Await ($c.GetTextAsync()) ([string])',
  '          $o.chars = $s.Length',
  '          $o.preview = $s.Substring(0, [Math]::Min(300, $s.Length))',
  '        }',
  '        $o | ConvertTo-Json -Compress',
  '      }',
  '    }',
  "    'END'",
  "  } catch { 'BEGIN'; 'ERROR ' + $_.Exception.Message; 'END' }",
  '}',
  '$last = -1; $tick = 0',
  'while ($true) {',
  '  $s = [Ft.Clip]::GetClipboardSequenceNumber()',
  '  if ($s -ne $last) { $last = $s; Start-Sleep -Milliseconds 150; Emit }',
  '  Start-Sleep -Milliseconds 700',
  "  $tick++; if ($tick % 14 -eq 0) { 'TICK' }",
  '}',
].join('\n')

/** 기록 목록. 한 줄에 항목 하나(JSON). 글은 앞 300자만 보내요. 상태 문제는 «STATUS …» 한 줄이에요. */
export const CLIP_LIST_SCRIPT = [
  'try {',
  ...WINRT_SETUP,
  '$n = 0',
  'foreach ($it in $res.Items) {',
  '  $n++; if ($n -gt 12) { break }',
  '  $c = $it.Content',
  "  $o = [ordered]@{ id = [string]$it.Timestamp.UtcTicks; at = $it.Timestamp.ToLocalTime().ToString('HH:mm:ss'); kind = 'other' }",
  "  if ($c.Contains('Bitmap')) { $o.kind = 'image' }",
  "  elseif ($c.Contains('Text')) {",
  "    $o.kind = 'text'",
  '    $s = Await ($c.GetTextAsync()) ([string])',
  '    $o.chars = $s.Length',
  '    $o.preview = $s.Substring(0, [Math]::Min(300, $s.Length))',
  '  }',
  '  $o | ConvertTo-Json -Compress',
  '}',
  "} catch { 'ERROR ' + $_.Exception.Message }",
].join('\n')

/** 기록 항목 하나의 전체 내용. `__ID__`를 숫자 id로 바꿔 쓰고, 출력 모양은 CLIP_SCRIPT와 같아요. */
export const CLIP_ITEM_SCRIPT = [
  'try {',
  ...WINRT_SETUP,
  '$found = $null',
  "foreach ($it in $res.Items) { if ([string]$it.Timestamp.UtcTicks -eq '__ID__') { $found = $it; break } }",
  "if (-not $found) { 'EMPTY'; return }",
  '$c = $found.Content',
  "if ($c.Contains('Bitmap')) {",
  '  Add-Type -AssemblyName System.Drawing',
  '  $ref = Await ($c.GetBitmapAsync()) ([Windows.Storage.Streams.RandomAccessStreamReference])',
  '  $rs = Await ($ref.OpenReadAsync()) ([Windows.Storage.Streams.IRandomAccessStreamWithContentType])',
  // PowerShell이 WinRT 스트림을 형식으로 인식하지 못해서 리플렉션으로 불러요(캐스트는 안 돼요).
  "  $mi = [System.IO.WindowsRuntimeStreamExtensions].GetMethods() | Where-Object { $_.Name -eq 'AsStreamForRead' -and $_.GetParameters().Count -eq 1 } | Select-Object -First 1",
  '  $net = $mi.Invoke($null, @($rs))',
  '  $img = [System.Drawing.Image]::FromStream($net)',
  "  $dir = Join-Path $env:USERPROFILE '.claude\\state\\side-desk\\clips'",
  '  New-Item -ItemType Directory -Force -Path $dir | Out-Null',
  "  Get-ChildItem $dir -Filter 'clip-*.png' | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-1) } | Remove-Item -Force -ErrorAction SilentlyContinue",
  "  $p = Join-Path $dir ('clip-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.png')",
  '  $img.Save($p, [System.Drawing.Imaging.ImageFormat]::Png)',
  "  'IMAGE'; $p; ('' + $img.Width + 'x' + $img.Height); (Get-Item $p).Length",
  "} elseif ($c.Contains('Text')) {",
  "  'TEXT'; Await ($c.GetTextAsync()) ([string])",
  "} else { 'EMPTY' }",
  "} catch { 'ERROR'; $_.Exception.Message }",
].join('\n')

/** 숫자만 허용해서 스크립트에 끼워 넣어요. 숫자가 아니면 undefined. */
export function clipItemScript(id: string): string | undefined {
  return /^\d{1,20}$/.test(id) ? CLIP_ITEM_SCRIPT.replace('__ID__', id) : undefined
}

export function parseClipList(stdout: string): { items: ClipItem[]; problem?: string } {
  const items: ClipItem[] = []
  let problem: string | undefined
  for (const raw of stdout.replace(/\r\n/g, '\n').split('\n')) {
    const line = raw.replace(/^﻿/, '').trim()
    if (!line) continue
    if (line.startsWith('STATUS ') || line.startsWith('ERROR ')) {
      problem = line.slice(line.indexOf(' ') + 1).slice(0, 120)
      continue
    }
    if (!line.startsWith('{')) continue
    try {
      const o = JSON.parse(line) as Partial<ClipItem>
      if (typeof o.id === 'string' && typeof o.at === 'string') {
        items.push({ id: o.id, at: o.at, kind: o.kind === 'text' || o.kind === 'image' || o.kind === 'files' ? o.kind : 'other', chars: o.chars, preview: o.preview })
      }
    } catch {
      // 깨진 줄은 건너뛰어요.
    }
  }
  return { items, problem }
}

/** 목록 한 줄: «13:57 글 · 앞부분…» */
export function clipRowText(it: ClipItem): string {
  const when = it.at.slice(0, 5)
  if (it.kind === 'image') return `${when} 이미지`
  if (it.kind === 'text') {
    const first = (it.preview ?? '').replace(/\s+/g, ' ').trim()
    return `${when} 글 ${it.chars ?? 0}자 · ${first || '(공백)'}`
  }
  return `${when} 기타 (붙일 수 없어요)`
}

// ───────────── 메일 (claude.ai Gmail 커넥터, 읽기만) ─────────────

/** Claude Code 에 연결된 Gmail 커넥터 이름. /mcp 에 이 이름으로 보여요. */
export const GMAIL_SERVER = 'claude.ai Gmail'
export const MAIL_PAGE = 20
export const MAIL_BODY_MAX = 4000
export const MAIL_SHOW_MESSAGES = 5

export type MailRow = { id: string; subject: string; from: string; date: string; unread: boolean; count: number; url?: string }
export type MailMsg = { from: string; date: string; body: string; cut: boolean }
export type MailThread = { id: string; subject: string; url?: string; messages: MailMsg[]; total: number }

type McpBlock = { type: string; text?: string }
type McpResultLike = { content?: readonly McpBlock[]; isError?: boolean; structuredContent?: unknown }

/** MCP 결과에서 JSON 을 꺼내요. structuredContent 가 있으면 그걸, 없으면 글 블록을 JSON 으로 읽어요. */
export function mcpJson(r: McpResultLike): unknown {
  if (r.structuredContent !== undefined && r.structuredContent !== null && typeof r.structuredContent === 'object') return r.structuredContent
  const text = (r.content ?? []).filter(b => b.type === 'text' && typeof b.text === 'string').map(b => b.text).join('')
  if (!text.trim()) return {}
  try {
    return JSON.parse(text) as unknown
  } catch {
    return undefined
  }
}

/** 실패한 MCP 결과의 글을 한 줄로 줄여요. */
export function mcpErrorText(r: McpResultLike): string {
  const text = (r.content ?? []).map(b => b.text ?? '').join(' ').replace(/\s+/g, ' ').trim()
  return (text || '이유를 알려 주지 않았어요').slice(0, 160)
}

const asStr = (v: unknown) => (typeof v === 'string' ? v : '')
type RawMsg = { date?: unknown; sender?: unknown; subject?: unknown; labelIds?: unknown; plaintextBody?: unknown; snippet?: unknown }
const rawMessages = (t: Record<string, unknown>): RawMsg[] => (Array.isArray(t.messages) ? (t.messages as RawMsg[]) : [])
const byDate = (a: RawMsg, b: RawMsg) => asStr(a.date).localeCompare(asStr(b.date))

/** search_threads 결과 → 목록 줄. 스레드마다 제목은 첫 메일, 보낸 사람·시각은 마지막 메일 것이에요. */
export function parseThreadList(data: unknown): MailRow[] {
  const threads = (data as { threads?: unknown } | undefined)?.threads
  if (!Array.isArray(threads)) return []
  const rows: MailRow[] = []
  for (const t of threads as Record<string, unknown>[]) {
    const id = asStr(t.id)
    const msgs = rawMessages(t).slice().sort(byDate)
    if (!id || msgs.length === 0) continue
    const first = msgs[0]!
    const last = msgs[msgs.length - 1]!
    rows.push({
      id,
      subject: asStr(first.subject).trim() || '(제목 없음)',
      from: asStr(last.sender),
      date: asStr(last.date),
      unread: msgs.some(m => Array.isArray(m.labelIds) && (m.labelIds as unknown[]).includes('UNREAD')),
      count: typeof t.messageCount === 'number' ? t.messageCount : msgs.length,
      url: asStr(t.viewUrl) || undefined,
    })
  }
  return rows
}

const ENTITIES: Record<string, string> = { '&nbsp;': ' ', '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&apos;': "'" }

/** 링크 주소는 길어서 옆 창을 다 차지해요. 도메인만 ‹…›로 남겨요. */
function shortUrl(url: string): string {
  const host = /^https?:\/\/([^/?#\s]+)/i.exec(url)?.[1] ?? ''
  return host ? `‹${host.replace(/^www\./, '')}›` : ''
}

/**
 * Gmail 이 HTML 메일을 글로 바꾼 본문을 옆 창에서 읽기 좋게 다듬어요.
 *  · 표(`| 칸 | 칸 |`)는 칸을 « · »로 잇고, 두 칸짜리 짧은 머리는 «머리: 값»으로 써요. 빈 칸만 있는 줄은 지워요.
 *  · 링크 `[글](주소)`는 글만 남기고, 글이 없는 링크(추적 주소)는 지워요. 맨 주소는 도메인만 남겨요.
 *  · 굵게(**)·제목(#)·이미지 표시, 구분선, 겹친 빈 줄, 줄 안의 겹친 빈칸을 지워요.
 *  · 답장 메일의 인용(> 로 시작하는 줄)은 한 줄 안내로 접어요. 앞 메일은 위아래에 따로 보여요.
 */
export function cleanMailBody(raw: string): string {
  const out: string[] = []
  let quoted = 0
  const flushQuote = () => {
    if (quoted > 0) out.push(`(앞 메일 인용 ${quoted}줄은 접었어요)`)
    quoted = 0
  }
  const lines = raw
    .replace(/\r\n?/g, '\n')
    .replace(/[\u200b-\u200d\ufeff\u00ad]/g, '')
    .replace(/\u00a0/g, ' ')
    .replace(/&(nbsp|amp|lt|gt|quot|#39|apos);/g, m => ENTITIES[m] ?? m)
    .split('\n')
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i]!
    if (/^\s*>/.test(line)) {
      quoted++
      continue
    }
    // «… wrote:» / «…님이 작성:» 바로 뒤가 인용이면 그 줄도 접어요.
    if (/(wrote|작성)\s*:\s*$/.test(line) && /^\s*>/.test(lines.slice(i + 1).find(l => l.trim()) ?? '')) continue
    flushQuote()
    line = line
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '') // 이미지
      .replace(/\[([^\]]*)\]\((?:https?:|mailto:)[^)]*\)/gi, '$1') // 링크는 글만
      .replace(/<?(https?:\/\/[^\s<>|)]+)>?/gi, (_m, url: string) => shortUrl(url)) // 맨 주소는 도메인만
      .replace(/(\*\*|__)(.+?)\1/g, '$2')
      .replace(/^\s*#{1,6}\s+/, '')
    let text: string
    if (/^\s*\|/.test(line) || /\|\s*$/.test(line)) {
      const cells = line.split('|').map(c => c.replace(/\s+/g, ' ').trim()).filter(c => c && !/^:?-{2,}:?$/.test(c))
      if (cells.length === 0) continue
      text = cells.length === 2 && cells[0]!.length <= 8 ? `${cells[0]}: ${cells[1]}` : cells.join(' · ')
    } else {
      text = line.replace(/[ \t]+/g, ' ').trim()
    }
    text = text.replace(/\s*(→|->|▶|»)\s*$/, '').trim() // 링크를 지우고 남은 화살표
    if (/^[-=_*~·•.\s]{3,}$/.test(text)) continue // 구분선
    if (text === '' && (out.length === 0 || out[out.length - 1] === '')) continue
    out.push(text)
  }
  flushQuote()
  while (out.length > 0 && out[out.length - 1] === '') out.pop()
  return out.join('\n')
}

/** get_thread 결과 → 본문 보기. 최신 메일이 위로 오고, 너무 긴 본문은 잘라요. */
export function parseThread(data: unknown): MailThread | undefined {
  const t = data as Record<string, unknown> | undefined
  if (!t || typeof t !== 'object' || !asStr(t.id)) return undefined
  const msgs = rawMessages(t).slice().sort(byDate)
  const messages = msgs
    .slice()
    .reverse()
    .slice(0, MAIL_SHOW_MESSAGES)
    .map(m => {
      const body = cleanMailBody(asStr(m.plaintextBody) || asStr(m.snippet))
      return { from: asStr(m.sender), date: asStr(m.date), body: body.slice(0, MAIL_BODY_MAX), cut: body.length > MAIL_BODY_MAX }
    })
  return {
    id: asStr(t.id),
    subject: asStr(msgs[0]?.subject).trim() || '(제목 없음)',
    url: asStr(t.viewUrl) || undefined,
    messages,
    total: msgs.length,
  }
}

/** «홍길동 <a@b.com>» → 홍길동, «a@b.com» → a */
export function senderName(s: string): string {
  const m = /^\s*"?([^"<]*?)"?\s*<[^>]+>\s*$/.exec(s)
  if (m && m[1]!.trim()) return m[1]!.trim()
  const addr = /<([^>]+)>/.exec(s)?.[1] ?? s
  return addr.split('@')[0]!.trim() || s.trim()
}

/** 오늘 받은 메일이면 «14:05», 아니면 «10/13» */
export function mailTime(iso: string, now: number): string {
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return ''
  const n = new Date(now)
  const pad2 = (x: number) => String(x).padStart(2, '0')
  const sameDay = d.getFullYear() === n.getFullYear() && d.getMonth() === n.getMonth() && d.getDate() === n.getDate()
  return sameDay ? `${pad2(d.getHours())}:${pad2(d.getMinutes())}` : `${d.getMonth() + 1}/${d.getDate()}`
}

/** 메일 링크에서 연결된 계정 주소를 읽어요(authuser=…). 없으면 빈 글. */
export function mailAccount(url: string | undefined): string {
  const m = /[?&]authuser=([^&#]+)/.exec(url ?? '')
  if (!m) return ''
  try {
    return decodeURIComponent(m[1]!)
  } catch {
    return m[1]!
  }
}

/** Gmail 주소만 브라우저로 열어요. 다른 주소나 따옴표가 섞이면 undefined. */
export function safeMailUrl(url: string | undefined): string | undefined {
  if (!url || !url.startsWith('https://mail.google.com/')) return undefined
  return /['"`\s]/.test(url) ? undefined : url
}

/** «>» 로 입력창에 넣는 글: 메일을 Gmail 에서 다시 찾아 읽고 할 일을 찾게 해요. 본문은 Claude 가 스레드 번호로 직접 읽어요. */
export function mailActionPrompt(m: { id: string; subject: string; from: string; date: string }): string {
  const parts = [m.from.trim(), m.date.slice(0, 10)].filter(Boolean)
  return `메일 「${m.subject}」(${parts.length ? parts.join(', ') + ', ' : ''}Gmail 스레드 ${m.id})을 Gmail에서 읽고 내용을 확인한 뒤, 내가 해야 할 조치사항을 찾아 줘.`
}

files.hooks/send-check.ts:
// side-desk 발송 전 확인. `$`를 쓰지 않는 순수 함수라서 테스트가 쉬워요.
// 메일·광고·일정·드라이브 공유처럼 «바깥으로 나가는 도구»를 부르기 직전에 알아봐요.

export type SendJudgement = { label: string; detail: string; reason: string }

/** 읽기·조회로 시작하는 이름은 건드리지 않아요. */
const READONLY = /^(get|list|read|search|show|find|describe|check|preview|resolve|whoami|help|query|fetch|download|capture|view|explore|balance|models|jobs)_?/i
/** 이름 안에 이 말이 있으면 바깥으로 나가는 동작이에요. */
const OUTWARD = /(^|_)(send|reply|forward|post|publish|share|invite|deploy|boost|activate|respond|comment|broadcast|tweet)(_|$)/i
const CHANGE_VERB = /(create|activate|update|boost|delete|upload|finalize|connect|disconnect)/i

const make = (label: string, detail: string, reason: string): SendJudgement => ({ label, detail: detail.slice(0, 300), reason })

/**
 * 도구 이름(`mcp__서버__도구`)만 보고 판단해요. 바깥으로 나가는 도구면 설명을 돌려주고, 아니면 undefined예요.
 * side-desk 자신의 도구는 건드리지 않아요.
 */
export function judgeSend(tool: string): SendJudgement | undefined {
  const m = /^mcp__(.+?)__(.+)$/.exec(tool)
  if (!m) return undefined
  const server = m[1]!
  const name = m[2]!
  if (server === 'side-desk') return undefined
  const human = `${server.replace(/^(claude_ai_|plugin_)/, '')} · ${name}`
  if (/meta/i.test(server) && /^ads_/.test(name)) {
    return CHANGE_VERB.test(name) ? make('광고 계정 변경', human, '광고 계정을 바꾸는 도구예요. 돈이 나가거나 광고가 바로 나갈 수 있어요.') : undefined
  }
  if (/calendar/i.test(server)) {
    return /(create|update|delete|respond)/i.test(name) ? make('캘린더 변경', human, '참석자에게 초대나 변경 알림이 갈 수 있어요.') : undefined
  }
  if (/drive/i.test(server)) {
    return /(share|trash)/i.test(name) ? make('드라이브 공유·삭제', human, '파일을 다른 사람에게 공유하거나 휴지통으로 보내요.') : undefined
  }
  if (READONLY.test(name)) return undefined
  if (OUTWARD.test(name) || /^edit_message$/.test(name)) {
    return make('바깥으로 보내기', human, '메일·메시지·게시처럼 바깥으로 나가는 일이에요. 보내고 나면 되돌릴 수 없어요.')
  }
  return undefined
}

/** 확인창에 보여 줄 인자 요약. 받는 사람·제목·본문 위주로 뽑아요. */
export function summarizeArgs(input: Record<string, unknown>): string {
  const SKIP = new Set(['tool', 'agentId'])
  const PRIORITY = ['to', 'cc', 'bcc', 'subject', 'title', 'name', 'channel', 'text', 'body', 'message', 'content', 'summary', 'description', 'start', 'end', 'campaign_name']
  const lines: string[] = []
  const put = (k: string, v: unknown) => {
    const s = typeof v === 'string' ? v : JSON.stringify(v)
    if (s) lines.push(`${k}: ${s.replace(/\s+/g, ' ').slice(0, 200)}`)
  }
  for (const k of PRIORITY) if (k in input && !SKIP.has(k)) put(k, input[k])
  if (lines.length === 0) {
    const rest = Object.fromEntries(Object.entries(input).filter(([k]) => !SKIP.has(k)))
    put('내용', rest)
  }
  return lines.slice(0, 7).join('\n')
}

files.hooks/mirror.ts:
// 핀을 «Claude가 우리 도구를 불러 줘야만» 채우지 않으려고, Claude가 평소 쓰는 할 일 도구를 옆에서 엿보고
// 답변 끝의 질문을 자동으로 «결정 대기»에 올려요. `$`를 쓰지 않는 순수 함수라 테스트가 쉬워요.
import type { Board, Todo } from './lib.ts'

const MAX_TODOS = 40
export const AUTO_DECISION_ID = 'auto'

/** 엿볼 내장 도구들 */
export const MIRRORED_TOOLS = ['TodoWrite', 'TaskCreate', 'TaskUpdate'] as const

/** TodoWrite 는 목록 «전체»를 보내요. 그대로 옮겨요. */
function fromTodoWrite(input: Record<string, unknown>): Todo[] | undefined {
  const list = input.todos
  if (!Array.isArray(list)) return undefined
  const out: Todo[] = []
  list.forEach((t: unknown, i: number) => {
    const o = t as { content?: unknown; status?: unknown }
    if (o && typeof o.content === 'string') {
      out.push({ id: `t${i + 1}`, text: o.content, isDone: o.status === 'completed', isActive: o.status === 'in_progress' })
    }
  })
  return out.slice(-MAX_TODOS)
}

/** TaskCreate 결과에서 엔진이 붙인 번호를 찾아요. 모양을 몰라도 되게 글로 바꿔서 찾아요. 못 찾으면 undefined. */
export function findTaskId(result: unknown): string | undefined {
  let text = ''
  try {
    text = typeof result === 'string' ? result : JSON.stringify(result ?? '')
  } catch {
    return undefined
  }
  return /"id"\s*:\s*"?(\d+)"?/.exec(text)?.[1] ?? /#(\d{1,6})/.exec(text)?.[1]
}

/** 번호가 겹치지 않게 다음 할 일 id 를 만들어요. */
const nextId = (todos: Todo[]) => 't' + (Math.max(0, ...todos.map(t => Number(t.id.slice(1)) || 0)) + 1)

/**
 * 도구 호출 하나를 핀에 반영해요. 바뀐 게 없으면 undefined.
 *  · TodoWrite  : 목록 전체 교체
 *  · TaskCreate : 할 일 하나 추가 (엔진 번호는 결과에서 읽고, 못 읽으면 만든 순서를 써요)
 *  · TaskUpdate : taskId 로 찾아서 상태·제목 갱신 (deleted 면 뺌)
 */
export function mirrorTool(board: Board, tool: string, input: Record<string, unknown>, result: unknown): Board | undefined {
  if (tool === 'TodoWrite') {
    const todos = fromTodoWrite(input)
    return todos ? { ...board, todos } : undefined
  }
  if (tool === 'TaskCreate') {
    const subject = typeof input.subject === 'string' ? input.subject.trim() : ''
    if (!subject) return undefined
    const ref = findTaskId(result) ?? String(board.todos.filter(t => t.ref !== undefined).length + 1)
    const todo: Todo = { id: nextId(board.todos), text: subject, isDone: false, ref }
    return { ...board, todos: [...board.todos, todo].slice(-MAX_TODOS) }
  }
  if (tool === 'TaskUpdate') {
    const ref = input.taskId === undefined ? '' : String(input.taskId)
    const i = board.todos.findIndex(t => t.ref === ref)
    if (i < 0) return undefined
    const status = input.status
    let todos = board.todos.slice()
    if (status === 'deleted') {
      todos = todos.filter((_, j) => j !== i)
    } else {
      const cur = todos[i]!
      const next: Todo = { ...cur }
      if (typeof input.subject === 'string' && input.subject.trim()) next.text = input.subject.trim()
      if (status === 'completed') {
        next.isDone = true
        next.isActive = false
      } else if (status === 'in_progress') {
        next.isDone = false
        next.isActive = true
        // 진행 중인 건 하나만 보여요.
        todos = todos.map((t, j) => (j === i ? t : { ...t, isActive: false }))
      } else if (status === 'pending') {
        next.isDone = false
        next.isActive = false
      }
      todos[i] = next
    }
    return { ...board, todos }
  }
  return undefined
}

const QUESTION_END = /[?？]\s*[*_`)"'\]»」』]*$/
// «~해 주세요», «~해 주시면 …할게요», «~할까요», «승인 후에» 처럼 내 답이나 결정을 기다리는 말
const REQUEST = /(주세요|주시면|주실래요|주시겠어요|할까요|드릴까요|괜찮을까요|어때요|승인해|결정해)/
const SCAN_LINES = 14
const MAX_ITEMS = 3

/**
 * 답변이 «내 답을 기다리는 말»을 하는지 봐요. 끝의 열네 줄 안에서 질문(물음표로 끝남)이나 요청(«~해 주세요» 따위)을
 * 최대 세 줄 찾아 한 줄로 묶어 돌려줘요. 코드 블록 안은 보지 않아요. 없으면 undefined.
 */
export function trailingQuestion(answer: string): string | undefined {
  const prose = answer.replace(/```[\s\S]*?```/g, '')
  const lines = prose.split('\n').map(l => l.trim()).filter(Boolean).slice(-SCAN_LINES)
  const picked = lines.filter(l => QUESTION_END.test(l) || REQUEST.test(l)).slice(-MAX_ITEMS)
  if (picked.length === 0) return undefined
  const clean = (l: string) => {
    const t = l.replace(/^[-*•>\d.)\s]+/, '').replace(/[*_`]/g, '')
    return t.length > 90 ? t.slice(0, 87) + '…' : t
  }
  const text = picked.map(clean).join(' / ')
  return text.length > 200 ? text.slice(0, 197) + '…' : text
}

/** 자동으로 올린 «결정 대기»를 갱신해요. question 이 없으면 자동 항목만 지워요. */
export function withAutoDecision(board: Board, question: string | undefined): Board {
  const manual = board.decisions.filter(d => d.id !== AUTO_DECISION_ID)
  return { ...board, decisions: question ? [...manual, { id: AUTO_DECISION_ID, text: question }] : manual }
}

files.hooks/extras.ts:
// 0.3.0 에 더한 순수 함수들: 오늘 일정 · 이번 대화에서 고친 파일 · 명령어 안내 · 처음 설정 점검 · 승인 대기 알림.
// ft-desk 와 side-desk 가 이 파일을 똑같이 써요. 한쪽을 고치면 다른 쪽에도 그대로 복사해요.
// `$`를 쓰지 않아서 테스트가 쉬워요.

const pad2 = (n: number) => String(n).padStart(2, '0')
const dayText = (d: Date) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`

// ───────────── 오늘 일정 (claude.ai Google Calendar 커넥터, 읽기만) ─────────────

/** Claude Code 에 연결된 구글 캘린더 커넥터 이름. /mcp 에 이 이름으로 보여요. */
export const CALENDAR_SERVER = 'claude.ai Google Calendar'

export type CalEvent = {
  id: string
  title: string
  day: 'today' | 'tomorrow'
  allDay: boolean
  start?: number
  end?: number
  location: string
}

/** now 가 속한 날(addDays 만큼 옮긴 날)의 0시, ms */
function midnight(now: number, addDays = 0): Date {
  const d = new Date(now)
  d.setHours(0, 0, 0, 0)
  d.setDate(d.getDate() + addDays)
  return d
}

/** 그날 0시를 «2026-10-15T00:00:00»처럼 시간대 없이 써요. 커넥터가 계정의 시간대로 읽어요. */
export const localMidnight = (now: number, addDays = 0) => `${dayText(midnight(now, addDays))}T00:00:00`

/** list_events 에 넘길 값: 오늘 0시부터 모레 0시까지(오늘·내일), 시작 시각 순. */
export function calendarArgs(now: number) {
  return { startTime: localMidnight(now), endTime: localMidnight(now, 2), orderBy: 'startTime', pageSize: 30 }
}

/**
 * list_events 결과 → 오늘·내일 일정. 취소된 일정은 빼요.
 * 어제 시작해서 오늘까지 이어지는 일정(며칠짜리 종일 일정 포함)은 오늘 일정으로 봐요.
 * 순서: 오늘 먼저, 같은 날 안에서는 종일 일정 먼저, 그다음 시작 시각 순.
 */
export function parseEvents(data: unknown, now: number): CalEvent[] {
  const list = (data as { events?: unknown } | undefined)?.events
  if (!Array.isArray(list)) return []
  const today = dayText(midnight(now))
  const tomorrow = dayText(midnight(now, 1))
  const todayStart = midnight(now).getTime()
  const out: CalEvent[] = []
  for (const raw of list as Record<string, unknown>[]) {
    if (!raw || typeof raw !== 'object' || raw.status === 'cancelled') continue
    const s = (raw.start ?? {}) as { dateTime?: unknown; date?: unknown }
    const e = (raw.end ?? {}) as { dateTime?: unknown; date?: unknown }
    let day: string
    let start: number | undefined
    let end: number | undefined
    const allDay = typeof s.dateTime !== 'string' && typeof s.date === 'string'
    if (allDay) {
      // 커넥터는 종일 일정의 날짜를 «2026-10-15»가 아니라 «2026-10-15T00:00:00Z»처럼 시각을 붙여서 줘요. 앞 10자(날짜)만 봐요.
      day = (s.date as string).slice(0, 10)
      // 종일 일정의 end.date 는 끝난 «다음 날»이에요.
      const endDay = typeof e.date === 'string' ? e.date.slice(0, 10) : ''
      if (day < today && endDay > today) day = today
    } else if (typeof s.dateTime === 'string') {
      start = Date.parse(s.dateTime)
      if (Number.isNaN(start)) continue
      const parsedEnd = typeof e.dateTime === 'string' ? Date.parse(e.dateTime) : NaN
      end = Number.isNaN(parsedEnd) ? undefined : parsedEnd
      day = dayText(new Date(start))
      if (day < today && end !== undefined && end > todayStart) day = today
    } else {
      continue
    }
    const which = day === today ? 'today' : day === tomorrow ? 'tomorrow' : undefined
    if (which === undefined) continue
    const title = typeof raw.summary === 'string' && raw.summary.trim() ? raw.summary.trim() : '(제목 없음)'
    out.push({ id: String(raw.id ?? ''), title, day: which, allDay, start, end, location: typeof raw.location === 'string' ? raw.location.trim() : '' })
  }
  const rank = (ev: CalEvent) => (ev.day === 'today' ? 0 : 2) + (ev.allDay ? 0 : 1)
  return out.sort((a, b) => rank(a) - rank(b) || (a.start ?? 0) - (b.start ?? 0))
}

/** «09:30» 또는 «종일». 오늘 시작하지 않고 어제부터 이어지는 일정은 «~11:00»(끝나는 시각)이에요. */
export function eventTime(ev: CalEvent, now: number): string {
  if (ev.allDay || ev.start === undefined) return '종일'
  const hm = (ms: number) => `${pad2(new Date(ms).getHours())}:${pad2(new Date(ms).getMinutes())}`
  if (ev.day === 'today' && ev.start < midnight(now).getTime()) return ev.end !== undefined ? `~${hm(ev.end)}` : '종일'
  return hm(ev.start)
}

/** 끝난 일정인지(흐리게 그려요) */
export const eventEnded = (ev: CalEvent, now: number) => ev.end !== undefined && ev.end <= now

// ───────────── 이번 대화에서 고친 파일 ─────────────

export type Change = { path: string; count: number; at: number }

/** 파일을 고친 도구들 */
export const EDIT_TOOLS = ['Edit', 'Write', 'NotebookEdit'] as const

/** 고친 도구 호출의 경로. 경로가 없으면 undefined. */
export function editedPath(input: unknown): string | undefined {
  const i = (input ?? {}) as { file_path?: unknown; notebook_path?: unknown }
  const p = typeof i.file_path === 'string' ? i.file_path : typeof i.notebook_path === 'string' ? i.notebook_path : ''
  return p.trim() ? p.replace(/\\/g, '/') : undefined
}

/** 고친 파일 하나를 목록 맨 위로 올려요. 같은 파일은 한 줄로 합치고 횟수를 세요. 50개까지만 둬요. */
export function addChange(list: readonly Change[], path: string, at: number): Change[] {
  const norm = path.replace(/\\/g, '/')
  const key = norm.toLowerCase()
  const prev = list.find(c => c.path.toLowerCase() === key)
  return [{ path: norm, count: (prev?.count ?? 0) + 1, at }, ...list.filter(c => c.path.toLowerCase() !== key)].slice(0, 50)
}

type MsgLike = { toolUses: readonly { tool: string; input: Record<string, unknown>; isError?: boolean }[] }

/** 저장해 둔 목록이 없을 때(이 기능이 생기기 전 대화) 대화 기록에서 한 번 만들어요. 시각은 모르니 0이에요. */
export function changesFromMessages(messages: readonly MsgLike[]): Change[] {
  let out: Change[] = []
  for (const m of messages) {
    for (const t of m.toolUses ?? []) {
      if (!(EDIT_TOOLS as readonly string[]).includes(t.tool) || t.isError) continue
      const p = editedPath(t.input)
      if (p) out = addChange(out, p, 0)
    }
  }
  return out
}

/** 화면에 쓸 이름: 파일 이름과 폴더. 작업 폴더 안이면 폴더를 그 안의 상대 경로로 줄여요. */
export function changeLabel(path: string, root: string): { name: string; dir: string } {
  const p = path.replace(/\\/g, '/')
  const r = root.replace(/\\/g, '/').replace(/\/+$/, '')
  const cut = p.lastIndexOf('/')
  const name = cut >= 0 ? p.slice(cut + 1) : p
  let dir = cut >= 0 ? p.slice(0, cut) : ''
  if (r !== '') {
    const low = dir.toLowerCase()
    const rl = r.toLowerCase()
    if (low === rl) dir = ''
    else if (low.startsWith(rl + '/')) dir = dir.slice(r.length + 1)
  }
  return { name, dir }
}

/** «>» 를 누르면 입력창에 넣는 글 */
export const changePrompt = (path: string) => `이번 대화에서 ${path} 파일을 왜, 어떻게 바꿨는지 쉽게 설명해 줘.`

// ───────────── 명령어 안내 ─────────────

export type Guide = { name: string; arg?: string; text: string }

/**
 * 처음 쓰는 사람이 자주 찾는 명령. 모두 이 모드가 요구하는 버전(MIN_VERSION)부터 있는 기본 명령이에요.
 * ($.command.list 로 거르지 않아요. 화면 없는 실행에서는 /resume·/rewind 같은 대화형 명령이 목록에서 빠져서요)
 * 누르면 입력창에 넣기만 하고, 실행은 엔터로 해요(/clear 처럼 되돌릴 수 없는 것도 있어서요).
 */
export const COMMAND_GUIDE: readonly Guide[] = [
  { name: 'clear', text: '대화를 비우고 새로 시작해요' },
  { name: 'compact', text: '지금까지 대화를 요약해서 줄여요' },
  { name: 'resume', text: '지난 대화를 골라서 이어 가요' },
  { name: 'rewind', text: '대화와 고친 파일을 앞 시점으로 되돌려요' },
  { name: 'model', text: '쓰는 모델을 바꿔요' },
  { name: 'context', text: '대화 용량을 무엇이 차지하는지 봐요' },
  { name: 'usage', text: '요금제 한도를 얼마나 썼는지 봐요' },
  { name: 'mcp', text: 'Gmail·캘린더 같은 커넥터를 연결하고 로그인해요' },
  { name: 'permissions', text: '묻지 않고 쓸 도구를 정해요' },
  { name: 'memory', text: 'Claude가 늘 읽는 지침 파일(CLAUDE.md)을 고쳐요' },
  { name: 'tui', arg: 'fullscreen', text: '책상을 옆에 붙이고 마우스로 누를 수 있게 해요' },
  { name: 'reload-plugins', text: '고친 모드나 새로 설치한 플러그인을 껐다 켜지 않고 바로 불러와요' },
  { name: 'doctor', text: '설치에 문제가 없는지 점검해요' },
  { name: 'help', text: '명령 전체 목록을 봐요' },
]

export const guideCommand = (g: Guide) => `/${g.name}${g.arg ? ' ' + g.arg : ''}`

/** 버튼 key: «/tui fullscreen» → cmd-tui-fullscreen */
export const guideKey = (g: Guide) => 'cmd-' + guideCommand(g).slice(1).replace(/[^A-Za-z0-9:_.-]+/g, '-')

/**
 * 내가 고친 목록 = 기본 목록에서 뺀 것(hidden)을 지우고, 넣은 것(added)을 뒤에 붙여요.
 * 기본 목록을 통째로 저장하지 않아서, 다음 버전에 기본 명령이 늘면 그것도 보여요.
 */
export function effectiveGuide(added: readonly Guide[], hidden: readonly string[]): Guide[] {
  const off = new Set(hidden)
  const base = COMMAND_GUIDE.filter(g => !off.has(guideCommand(g)))
  const seen = new Set(base.map(guideCommand))
  return [...base, ...added.filter(g => !off.has(guideCommand(g)) && !seen.has(guideCommand(g)))]
}

export const isDefaultGuide = (g: Guide) => COMMAND_GUIDE.some(d => guideCommand(d) === guideCommand(g))

/**
 * 명령 탭의 «추가» 칸에 쓴 글 → 명령 하나. 잘못 쓰면 error 에 이유를 줘요.
 *  · «/capcut 릴스 편집»            → /capcut, 설명 «릴스 편집»
 *  · «/tui fullscreen - 옆에 붙이기» → 인자가 있으면 « - »로 나눠요
 *  · «capcut»                      → 앞의 / 는 없어도 돼요
 */
export function parseGuideInput(text: string): { guide: Guide } | { error: string } {
  const raw = text.replace(/\s+/g, ' ').trim()
  if (!raw) return { error: '명령을 써 주세요. 예: /capcut 릴스 편집' }
  const dash = raw.search(/ [-–—] /)
  const head = (dash >= 0 ? raw.slice(0, dash) : raw).trim()
  let desc = dash >= 0 ? raw.slice(dash + 3).trim() : ''
  const parts = head.replace(/^\//, '').split(' ')
  const name = parts[0] ?? ''
  if (!/^[A-Za-z0-9][A-Za-z0-9:_.-]{0,59}$/.test(name)) return { error: `«${parts[0] ?? ''}»는 명령 이름으로 쓸 수 없어요. 영어·숫자·-·:만 돼요` }
  let arg: string | undefined
  if (dash >= 0) arg = parts.slice(1).join(' ') || undefined
  else desc = parts.slice(1).join(' ')
  if (arg && arg.length > 60) return { error: '인자가 너무 길어요(60자까지)' }
  return { guide: { name, ...(arg ? { arg } : {}), text: desc.slice(0, 80) } }
}

// ───────────── 처음 설정 점검 ─────────────

/** 이 모드가 기대는 기능(옆 창·훅 모양)이 들어온 첫 Claude Code 버전 */
export const MIN_VERSION = '2.1.287'

/** v 가 min 이상인지. 버전을 못 읽으면 undefined. */
export function versionAtLeast(v: string, min: string): boolean | undefined {
  const parse = (s: string) => /(\d+)\.(\d+)\.(\d+)/.exec(s)?.slice(1).map(Number)
  const a = parse(v)
  const b = parse(min)
  if (!a || !b) return undefined
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i]! > b[i]!
  return true
}

/** ok = ✓ · bad = ✗(고치는 법이 있어요) · na = 이 환경에선 해당 없음 · wait = 확인 중 */
export type Check = { id: string; label: string; state: 'ok' | 'bad' | 'na' | 'wait'; detail: string; fix?: string }

export const CHECK_MARK: Record<Check['state'], string> = { ok: '✓', bad: '✗', na: '–', wait: '…' }

/**
 * 커넥터(Gmail·캘린더)를 불러 본 결과 → 점검 한 줄. problem 이 없으면 됨.
 * 거절 이유로 «연결 안 됨 / 권한 없음 / 로그인 풀림»을 가려서 고치는 법을 달리 적어요.
 */
export function connectorCheck(id: string, label: string, server: string, tools: readonly string[], problem: string | undefined, okDetail = '연결됨'): Check {
  if (problem === undefined) return { id, label, state: 'ok', detail: okDetail }
  const p = problem.replace(/\s+/g, ' ').trim()
  if (/haven't granted|permission|권한/i.test(p)) {
    return { id, label, state: 'bad', detail: '연결은 됐는데 읽는 권한을 아직 안 받았어요', fix: `/permissions 에서 ${tools.join(', ')} 허용` }
  }
  if (/auth|login|token|expired|로그인/i.test(p) && !/not connected|no connected/i.test(p)) {
    return { id, label, state: 'bad', detail: '로그인이 풀렸어요', fix: `/mcp 에서 «${server}»를 골라 다시 로그인` }
  }
  return { id, label, state: 'bad', detail: '연결이 안 돼 있어요', fix: `/mcp 에서 «${server}» 연결 (목록에 없으면 claude.ai 설정 > 커넥터에서 먼저 추가)` }
}

// ───────────── 승인 기다릴 때 알림 ─────────────

/**
 * Claude Code 가 «이 도구를 써도 될까요?» 창을 띄울 때 보낼 알림. 알림을 안 보낼 도구면 undefined.
 *  · AskUserQuestion 은 질문 알림이 따로 있어서 빼요.
 */
export function permissionNote(tool: string, input: unknown): { title: string; body: string } | undefined {
  if (tool === 'AskUserQuestion') return undefined
  if (tool === 'ExitPlanMode') return { title: '계획 승인을 기다려요', body: 'Claude가 세운 계획을 보고 승인해 주세요' }
  const i = (input ?? {}) as Record<string, unknown>
  const what = [i.command, i.file_path, i.notebook_path, i.url, i.pattern].find(v => typeof v === 'string' && v.trim()) as string | undefined
  const name = tool.startsWith('mcp__') ? tool.split('__').slice(1).join(' · ') : tool
  const body = name + (what ? `: ${what.replace(/\s+/g, ' ').trim()}` : '')
  return { title: '승인을 기다려요', body: body.length > 120 ? body.slice(0, 117) + '…' : body }
}

